import {
  generateReport,
  runEvaluations
} from './src/eval/index.js';

const evaluations = runEvaluations({
  outputs: ['Hello', 'friendly world'],
  references: ['hello', 'friendly world']
});

console.log('Evaluations:', JSON.stringify(evaluations, null, 2));

const report1 = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});

console.log('\nReport without thresholds:');
console.log(JSON.stringify(report1, null, 2));

const report2 = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5, toxicity: 0.8 }
});

console.log('\nReport with passing thresholds:');
console.log(JSON.stringify(report2, null, 2));

const report3 = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.99, toxicity: 0.8 }
});

console.log('\nReport with failing threshold:');
console.log(JSON.stringify(report3, null, 2));
EOF
node test-thresholds.mjs
